#!/usr/bin/env python3
# Shader-side virtual texturing (dm/android/gfx_vk_vt.c) as a SPIR-V transform of the translator's fragment shaders, applied by shader_vk.py (--vt, or DM_VK_VT=1 when it runs).
# The stock Adreno 840 driver gives sparse residency to no block-compressed format, so Mario Kart World's terrain arrays (8192x8192x68, BC6H and ASTC 8x8, 12 levels, 3-12 % of
# their tiles mapped) are dense images from a coarse level (gfx_vk_tex.c dense_*, DM_VK_SPARSE_DENSE_MB: from level 3 or 4). Every shader that samples them (1,118 of 1.8.0's
# pixel shaders, DriveRefreshUber GridifyGeo / Stage / Others; 3,314 bindings, always the texture slots 0-2 of c2) does it one way: TMML, then TEX.LL at the larger of that level
# and clamps from its uniforms and storage buffer, i.e. textureLod(T, vec3(uv, layer), max(clamp, textureQueryLod(T, uv).x)). Such a binding (a float 2D array read only by
# OpImageQueryLod and by OpImageSampleExplicitLod with a Lod operand alone) is a candidate: both calls go through vt_qlod / vt_sample (TEMPLATE_GLSL), which per draw (vt_ctl,
# which the replay writes) leave the texture as it is (mode 0), move the game's LOD from texture levels to the dense image's (mode 1: the image starts at level `first`, which the
# game's clamp does not know of), or read the levels finer than `first` from a pool of 64 KB tiles in their own compressed format through a page table (mode 2), falling back to
# the dense image where a tile has no slot yet and asking for it (vt_fb). The transform adds the bindings vt_pool_<k> (one a candidate: the pool of its format, with the game's
# filters), vt_ctl, vt_pt and vt_fb after the shader's own; shader_vk.py's reflection files them as the kinds vt_pool / vt_ctl / vt_pt / vt_fb (a backend that does not know them
# binds zeros, which is mode 0 everywhere). A shader with a discard, a depth or sample mask write, or stores and atomics of its own gets the variant without requests (early
# fragment tests would change what it does, and our stores without them would keep the driver from testing early); the others get EarlyFragmentTests, which changes nothing
# for them and keeps occluded fragments from asking for tiles (Mario Kart World 1.8.0: 1,207 of the 1,220 shaders transformed, 13 discard).
#   from spv_vt import transform; spv2, info = transform(spv)        (info None: the shader is unchanged)
#   spv_vt.py <in.spv> <out.spv>                                     (one module; prints what it did)
#   spv_vt.py --regen                                                (recompiles the template with glslangValidator or glslc into TEMPLATE_SPV)
import base64, hashlib, struct, sys

TEMPLATE_GLSL = r'''#version 450
// Shader-side virtual texturing (gfx_vk_vt.c): the functions spv_vt.py calls in place of a candidate binding's textureQueryLod and textureLod.
// vt_ctl per draw: e[0] = (request region word offset, its words, 0, 0); candidate k: e[1 + 3k] = (mode | 4 linear mipmaps | wrap U << 3 | wrap V << 5, first, page table base, layers),
// e[2 + 3k] = (width | height << 16 of level 0, log2 tile width | log2 tile height << 8 | border texels << 16, tiled levels, tiles a layer), e[3 + 3k] = (lowest LOD, highest LOD as
// floats, 0, 0). vt_pt: a word a 64 KB tile, slot + 1 in bits 0-15 (0: none), bit 16 the game maps it, bit 17 on probation; vt_fb: bit i asks for page table word i
layout(set = 0, binding = 0, std140) uniform VtCtl { uvec4 e[25]; } vt_ctl;
layout(set = 0, binding = 1, std430) readonly buffer VtPt { uint w[]; } vt_pt;
#if VT_FB
layout(set = 0, binding = 2, std430) buffer VtFb { uint w[]; } vt_fb;
#define VT_REQ(i) { uint wi_ = (i) >> 5u, bit_ = 1u << ((i) & 31u); if (wi_ < hd.y && (vt_fb.w[hd.x + wi_] & bit_) == 0u) atomicOr(vt_fb.w[hd.x + wi_], bit_); }
#else
#define VT_REQ(i) {}
#endif

// textureQueryLod as the whole texture would answer it: the dense image's unclamped LOD (y) is the texture's minus first; x clamped as the sampler and the levels clamp it
vec2 vt_qlod(sampler2DArray orig, uint k, vec2 uv) {
    vec2 q = textureQueryLod(orig, uv);
    uvec4 a = vt_ctl.e[1u + 3u * k];
    if ((a.x & 3u) == 0u) return q;
    uvec4 c = vt_ctl.e[3u + 3u * k];
    float raw = q.y + float(a.y);
    return vec2(clamp(raw, uintBitsToFloat(c.x), uintBitsToFloat(c.y)), raw);
}

// Level l (< first) at the wrapped coordinate uv: st 0 sampled into v, 1 the game maps the tile and it has no slot (asked for), 2 the game does not map it (zeros, as NVN reads it).
// A slot is the tile with a border of one block of its neighbours (the wrapped ones at the edges): bilinear filtering never leaves it
#define VT_LEVEL(l, st, v) { \
    uint wl_ = max(W >> (l), 1u), hl_ = max(H >> (l), 1u); vec2 sz_ = vec2(float(wl_), float(hl_)); vec2 t_ = uv * sz_; \
    if (mu != 1u) t_.x = clamp(t_.x, 0.5, sz_.x - 0.5); \
    if (mv != 1u) t_.y = clamp(t_.y, 0.5, sz_.y - 0.5); \
    uint nx_ = max(wl_ >> tws, 1u), ny_ = max(hl_ >> ths, 1u); \
    uint tx_ = min(uint(t_.x) >> tws, nx_ - 1u), ty_ = min(uint(t_.y) >> ths, ny_ - 1u); \
    uint lo_ = 0u; for (uint j_ = 0u; j_ < (l); j_++) lo_ += max((W >> j_) >> tws, 1u) * max((H >> j_) >> ths, 1u); \
    uint ix_ = a.z + layer * b.w + lo_ + ty_ * nx_ + tx_; uint e_ = vt_pt.w[ix_]; uint sl_ = e_ & 0xffffu; \
    if (sl_ == 0u) { v = vec4(0.0); st = (e_ & 0x10000u) != 0u ? 1u : 2u; if (st == 1u) VT_REQ(ix_) } \
    else { st = 0u; if ((e_ & 0x20000u) != 0u) VT_REQ(ix_) \
        vec2 q_ = t_ - vec2(float(tx_ << tws), float(ty_ << ths)) + float(bd); \
        vec2 ss_ = vec2(float((1u << tws) + 2u * bd), float((1u << ths) + 2u * bd)); \
        v = textureLod(pool, vec3(q_ / ss_, float(sl_ - 1u)), fr); } }

float vt_wrap(float u, uint m) {   // the sampler's address mode on a normalized coordinate: 0 clamp (to edge or border), 1 repeat, 2 mirrored repeat, 3 mirror clamp to edge
    if (m == 1u) return fract(u);
    if (m == 2u) { float t = mod(u, 2.0); return t > 1.0 ? 2.0 - t : t; }
    if (m == 3u) return min(abs(u), 1.0);
    return clamp(u, 0.0, 1.0);
}

// textureLod(orig, p, lod), lod in the texture's levels (the game's)
vec4 vt_sample(sampler2DArray orig, sampler2DArray pool, uint k, vec3 p, float lod) {
    uvec4 a = vt_ctl.e[1u + 3u * k];
    uint mode = a.x & 3u;
    if (mode == 0u) return textureLod(orig, p, lod);
    float first = float(a.y);
    if (mode == 1u || lod >= first) return textureLod(orig, p, max(lod - first, 0.0));
    uvec4 b = vt_ctl.e[2u + 3u * k];
    uvec4 hd = vt_ctl.e[0];
    float L = max(lod, 0.0);
    bool lin = (a.x & 4u) != 0u;
    uint l0 = lin ? uint(L) : (L <= 0.5 ? 0u : uint(ceil(L + 0.5)) - 1u);
    if (float(l0) >= first) return textureLod(orig, p, 0.0);
    float fr = lin ? L - float(l0) : 0.0;
    uint mu = (a.x >> 3u) & 3u, mv = (a.x >> 5u) & 3u;
    vec2 uv = vec2(vt_wrap(p.x, mu), vt_wrap(p.y, mv));
    uint layer = uint(clamp(roundEven(p.z), 0.0, float(max(a.w, 1u) - 1u)));
    uint W = b.x & 0xffffu, H = b.x >> 16u, tws = b.y & 31u, ths = (b.y >> 8u) & 31u, bd = (b.y >> 16u) & 255u;
    uint st0; vec4 v0;
    VT_LEVEL(l0, st0, v0)
    if (st0 == 1u) return textureLod(orig, p, 0.0);
    if (fr == 0.0) return v0;
    vec4 v1;
    if (float(l0 + 1u) >= first) v1 = textureLod(orig, p, 0.0);
    else { uint st1; VT_LEVEL(l0 + 1u, st1, v1) if (st1 == 1u) return textureLod(orig, p, 0.0); }
    return mix(v0, v1, fr);
}

layout(set = 0, binding = 3) uniform sampler2DArray vt_tmpl_orig;   // the template's own entry point and resources (not copied: the game's calls pass its own)
layout(set = 0, binding = 4) uniform sampler2DArray vt_tmpl_pool;
layout(location = 0) in vec4 vt_tmpl_in;
layout(location = 0) out vec4 vt_tmpl_out;
void main() { vt_tmpl_out = vt_sample(vt_tmpl_orig, vt_tmpl_pool, 0u, vt_tmpl_in.xyz, vt_tmpl_in.w) + vt_qlod(vt_tmpl_orig, 1u, vt_tmpl_in.xy).xyxy; }
'''
TEMPLATE_NC = 8   # candidates a shader may have (vt_ctl's e[1 + 3 * TEMPLATE_NC]; gfx_vk_vt.h VT_NC)
# glslangValidator -V --target-env vulkan1.1 -DVT_FB=<1|0> of TEMPLATE_GLSL, then OPT_PASSES, and its SHA-256 (spv_vt.py --regen writes both; tests/test_vk_vt.py checks the hash)
TEMPLATE_SHA = 'dd5266a18e678d0c08cc5105572ae59e918fc4c759694569c99ec8a752e5e545'
TEMPLATE_SPV = {1: '', 0: ''}

# ---- a SPIR-V module as a list of instructions ----
OpName, OpMemberName, OpString, OpExtension, OpExtInstImport, OpExtInst, OpMemoryModel, OpEntryPoint, OpExecutionMode, OpCapability = 5, 6, 7, 10, 11, 12, 14, 15, 16, 17
OpTypeVoid, OpTypeBool, OpTypeInt, OpTypeFloat, OpTypeVector, OpTypeMatrix, OpTypeImage, OpTypeSampler, OpTypeSampledImage = 19, 20, 21, 22, 23, 24, 25, 26, 27
OpTypeArray, OpTypeRuntimeArray, OpTypeStruct, OpTypePointer, OpTypeFunction = 28, 29, 30, 32, 33
OpConstantTrue, OpConstantFalse, OpConstant, OpConstantComposite, OpConstantNull, OpUndef = 41, 42, 43, 44, 46, 1
OpFunction, OpFunctionParameter, OpFunctionEnd, OpFunctionCall, OpVariable, OpLoad, OpStore, OpDecorate, OpMemberDecorate = 54, 55, 56, 57, 59, 61, 62, 71, 72
OpImageSampleExplicitLod, OpImageQueryLod, OpLabel, OpKill, OpTerminateInvocation, OpDemoteToHelperInvocation = 88, 105, 248, 252, 4416, 5380
TYPES = set(range(19, 40)) | {322, 4456, 5341, 5358}   # OpType* (and the ones of later versions and extensions)
CONSTS = {OpConstantTrue, OpConstantFalse, OpConstant, OpConstantComposite, OpConstantNull, OpUndef}
AGGREGATES = {OpTypeStruct, OpTypeArray, OpTypeRuntimeArray}   # may be declared twice, and their decorations are their own: never shared with the shader's
# instructions with no result (the rest have a result type in word 1 and a result id in word 2, except the types, OpExtInstImport, OpString, OpLabel, OpDecorationGroup: word 1)
NO_RESULT = {0, 2, 3, 4, 5, 6, 8, 10, 14, 15, 16, 17, 56, 62, 63, 64, 71, 72, 74, 75, 99, 218, 219, 220, 221, 224, 225, 228, 246, 247, 249, 250, 251, 252, 253, 254, 255,
             256, 257, 317, 330, 331, 332, 333, 4416, 5380, 5364, 5365, 5294, 5295}
RESULT_ONLY = {OpExtInstImport, OpString, OpLabel, 73} | TYPES
DEC_BINDING, DEC_SET, DEC_BUILTIN = 33, 34, 11
BUILTIN_FRAGDEPTH, BUILTIN_SAMPLEMASK = 22, 20
EM_EARLY_FRAGMENT_TESTS = 9
EM_DEPTH = {12, 14, 15, 5027}   # DepthReplacing, DepthGreater, DepthLess, StencilRefReplacingEXT
SC_UNIFORM_CONSTANT, SC_FUNCTION = 0, 7


def parse(spv):
    if len(spv) < 20 or len(spv) % 4: raise ValueError('not a SPIR-V module')
    w = list(struct.unpack(f'<{len(spv) // 4}I', spv))
    if w[0] != 0x07230203: raise ValueError('not a SPIR-V module (or not little-endian)')
    ins, i = [], 5
    while i < len(w):
        n = w[i] >> 16
        if n == 0 or i + n > len(w): raise ValueError(f'a truncated instruction at word {i}')
        ins.append(w[i:i + n]); i += n
    return w[:5], ins


def emit(hdr, ins):
    out = list(hdr)
    for x in ins: out += x
    return struct.pack(f'<{len(out)}I', *out)


def op_of(x): return x[0] & 0xffff
def mk(op, *ops): return [(len(ops) + 1) << 16 | op, *ops]
def lit_str(s):
    b = s.encode() + b'\0'; b += b'\0' * (-len(b) % 4)
    return list(struct.unpack(f'<{len(b) // 4}I', b))
def str_words(words): return (bytes(struct.pack(f'<{len(words)}I', *words)).split(b'\0')[0].decode(), (len(bytes(struct.pack(f'<{len(words)}I', *words)).split(b'\0')[0]) + 4) // 4)
def str_of(words): return str_words(words)[0]


def result_id(x):
    op = op_of(x)
    if op in NO_RESULT: return None
    if op in RESULT_ONLY: return x[1]
    return x[2] if len(x) > 2 else None


def id_operands(x):
    """The word positions of x that hold ids, the result's included: what an id map rewrites (the opcodes of the template and of a module's global section; the default is that
    every operand is an id, which holds for the arithmetic, logic, conversion, composite construction, access chain, atomic, phi and call instructions)"""
    op, n = op_of(x), len(x)
    if op in (OpName, OpMemberName, OpDecorate, OpMemberDecorate, OpExecutionMode, OpExtInstImport, OpString, OpLabel, 249, 254, 247): return [1]
    if op in (OpCapability, OpExtension, OpMemoryModel, 3, 4, 330, OpFunctionEnd, 253, 255, OpKill, OpTerminateInvocation, OpDemoteToHelperInvocation, 8, 317): return []
    if op == OpEntryPoint: return [2] + list(range(3 + str_words(x[3:])[1], n))
    if op in (OpTypeVoid, OpTypeBool, OpTypeInt, OpTypeFloat, OpTypeSampler): return [1]
    if op in (OpTypeVector, OpTypeMatrix, OpTypeSampledImage, OpTypeRuntimeArray, OpTypeImage): return [1, 2]
    if op == OpTypePointer: return [1, 3]
    if op in (OpConstant, 50): return [1, 2]              # (and OpSpecConstant): the value is a literal
    if op == OpVariable: return [1, 2] + ([4] if n > 4 else [])
    if op == OpFunction: return [1, 2, 4]
    if op == OpExtInst: return [1, 2, 3] + list(range(5, n))
    if op == OpLoad: return [1, 2, 3]                     # (memory operands after)
    if op == OpStore: return [1, 2]
    if op == 81: return [1, 2, 3]                         # OpCompositeExtract: indices are literals
    if op == 82: return [1, 2, 3, 4]                      # OpCompositeInsert
    if op == 79: return [1, 2, 3, 4]                      # OpVectorShuffle: components are literals
    if op == 246: return [1, 2]                           # OpLoopMerge
    if op == 250: return [1, 2, 3]                        # OpBranchConditional (weights are literals)
    if op == 251: return [1, 2] + list(range(4, n, 2))    # OpSwitch, 32-bit selectors: (literal, label) pairs
    if op in (87, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97, 98, 99, 305, 306, 307, 308, 313, 314, 315, 320):   # image instructions: ids, the operands mask, ids
        fixed = {87: 5, 88: 5, 89: 6, 90: 6, 91: 5, 92: 5, 93: 6, 94: 6, 95: 5, 96: 6, 97: 6, 98: 5, 99: 4, 305: 5, 306: 5, 307: 6, 308: 6, 313: 5, 314: 6, 315: 6, 320: 5}[op]
        return [i for i in range(1, n) if i != fixed]
    return list(range(1, n))


class Module:
    def __init__(self, spv):
        self.hdr, self.ins = parse(spv)
        self.defs = {}
        for x in self.ins:
            r = result_id(x)
            if r is not None: self.defs[r] = x

    @property
    def bound(self): return self.hdr[3]

    def names(self):
        return {x[1]: str_of(x[2:]) for x in self.ins if op_of(x) == OpName}

    def first_function(self):
        return next((i for i, x in enumerate(self.ins) if op_of(x) == OpFunction), len(self.ins))


def _key(x, idmap):
    """A type's or constant's structure, its operands mapped, without its result id: an equal key is the same type, which SPIR-V does not let a module declare twice"""
    op = op_of(x); ids = set(id_operands(x)); rid = 1 if op in RESULT_ONLY else 2
    return (op,) + tuple(('i', idmap.get(x[i], x[i])) if i in ids else ('l', x[i]) for i in range(1, len(x)) if i != rid)


# ---- the template ----
_TEMPLATE = {}
def template(fb):
    if fb not in _TEMPLATE:
        b = TEMPLATE_SPV.get(fb)
        if not b: raise RuntimeError('spv_vt.py has no compiled template: run spv_vt.py --regen')
        _TEMPLATE[fb] = Module(base64.b64decode(b))
    return _TEMPLATE[fb]


def compile_template(compiler, fb, out):
    import os, subprocess, tempfile
    with tempfile.TemporaryDirectory() as d:
        src = os.path.join(d, 'vt.frag'); open(src, 'w').write(TEMPLATE_GLSL)
        cmd = [compiler, '-V', '--target-env', 'vulkan1.1', f'-DVT_FB={fb}', src, '-o', out] if 'glslang' in os.path.basename(compiler) else \
              [compiler, '--target-env=vulkan1.1', f'-DVT_FB={fb}', '-fshader-stage=frag', src, '-o', out]
        r = subprocess.run(cmd, capture_output=True, text=True)
        if r.returncode: raise RuntimeError(r.stdout + r.stderr)


# spirv-opt passes for the template when the tool is there (the NDK's shader-tools have it): its locals in SSA form, its dead code gone (19 KB -> 14 KB), its functions kept
# (no inlining: the transform calls them). The driver optimizes the shaders anyway; this keeps the bundle and the pipelines' SPIR-V smaller
OPT_PASSES = ['--ssa-rewrite', '--eliminate-local-single-block', '--eliminate-local-single-store', '--eliminate-local-multi-store', '--ccp', '--simplify-instructions',
              '--redundancy-elimination', '--eliminate-dead-code-aggressive', '--eliminate-dead-branches', '--merge-blocks', '--simplify-instructions', '--eliminate-dead-code-aggressive']


def regen(compiler=None, opt=None):
    import os, shutil, subprocess, tempfile
    comp = compiler or shutil.which('glslangValidator') or shutil.which('glslc')
    if not comp: raise RuntimeError('glslangValidator or glslc is needed')
    opt = opt or shutil.which('spirv-opt'); out = {}
    with tempfile.TemporaryDirectory() as d:
        for fb in (1, 0):
            o = os.path.join(d, f'vt{fb}.spv'); compile_template(comp, fb, o)
            if opt:
                r = subprocess.run([opt, '--target-env=vulkan1.1', *OPT_PASSES, o, '-o', o + '.opt'], capture_output=True, text=True)
                if r.returncode: raise RuntimeError(r.stdout + r.stderr)
                o += '.opt'
            out[fb] = base64.b64encode(open(o, 'rb').read()).decode()
    return hashlib.sha256(TEMPLATE_GLSL.encode()).hexdigest(), out


# ---- the shader's candidates ----
def _image_ok(m, t):
    """t a sampled image type of a float 2D array image, single-sampled and sampled (the template's parameters)"""
    x = m.defs.get(t)
    if not x or op_of(x) != OpTypeSampledImage: return False
    im = m.defs.get(x[2])
    if not im or op_of(im) != OpTypeImage: return False
    st = m.defs.get(im[2])
    return bool(st) and op_of(st) == OpTypeFloat and st[2] == 32 and im[3] == 1 and im[4] in (0, 2) and im[5] == 1 and im[6] == 0 and im[7] == 1


def candidates(m):
    """{variable id: its sampled image type}: the float 2D-array combined samplers read only through loads whose results are sampled only by OpImageSampleExplicitLod with
    a Lod operand alone and queried only by OpImageQueryLod, sampled at least once"""
    var_t = {}
    for x in m.ins:
        if op_of(x) == OpVariable and x[3] == SC_UNIFORM_CONSTANT:
            p = m.defs.get(x[1])
            if p and op_of(p) == OpTypePointer and _image_ok(m, p[3]): var_t[x[2]] = p[3]
    if not var_t: return {}
    loads, bad, sampled = {}, set(), set()
    for x in m.ins:
        op = op_of(x)
        if op == OpLoad and x[3] in var_t: loads[x[2]] = x[3]; continue
        if op in (OpName, OpDecorate, OpEntryPoint): continue
        for i in id_operands(x):
            if x[i] in var_t and not (op == OpVariable and i == 2): bad.add(x[i])   # used other than by a load
    for x in m.ins:
        op = op_of(x)
        if op in (OpName, OpDecorate): continue
        for i in id_operands(x):
            v = loads.get(x[i])
            if v is None or (op == OpLoad and i == 2): continue
            if op == OpImageQueryLod and i == 3 and len(x) == 5: continue
            if op == OpImageSampleExplicitLod and i == 3 and len(x) == 7 and x[5] == 2: sampled.add(v); continue
            bad.add(v)
    return {v: t for v, t in var_t.items() if v not in bad and v in sampled}


def hazard(m):
    """What early fragment tests would change: a discard or a demotion, a depth, stencil reference or sample mask output, or a side effect of the shader's own (a store to a
    storage buffer or an image, an atomic: without early tests an occluded fragment makes it, with them not)"""
    ptr_sc = {x[1]: x[2] for x in m.ins if op_of(x) == OpTypePointer}
    res_t = {result_id(x): x[1] for x in m.ins if op_of(x) not in NO_RESULT and op_of(x) not in RESULT_ONLY and len(x) > 2}
    for x in m.ins:
        op = op_of(x)
        if op in (OpKill, OpTerminateInvocation, OpDemoteToHelperInvocation, 99, 4469) or 227 <= op <= 242: return True   # (99 OpImageWrite, 227-242 the atomics, 4469 OpImageSparseWrite)
        if op == OpStore and ptr_sc.get(res_t.get(x[1])) in (2, 11, 12, 5349): return True   # Uniform (a buffer block), Image, StorageBuffer, PhysicalStorageBuffer
        if op == OpDecorate and len(x) > 3 and x[2] == DEC_BUILTIN and x[3] in (BUILTIN_FRAGDEPTH, BUILTIN_SAMPLEMASK, 5014): return True   # (5014 FragStencilRefEXT)
        if op == OpExecutionMode and len(x) > 2 and x[2] in EM_DEPTH: return True
    return False


def transform(spv, max_cands=TEMPLATE_NC):
    """(the shader with its candidates sampled through the template, info), or (spv, None) when it has none or is not one fragment shader.
    info: cands [(binding, k)], pools [vt_pool_k's binding], ctl / pt / fb (fb None in the variant without requests) bindings, early (EarlyFragmentTests added),
    queries / samples (the calls made)"""
    m = Module(spv)
    ep = [x for x in m.ins if op_of(x) == OpEntryPoint]
    if len(ep) != 1 or ep[0][1] != 4: return spv, None   # Fragment only: the template's textureQueryLod takes implicit derivatives
    cand = candidates(m)
    if not cand: return spv, None
    deco = {}
    for x in m.ins:
        if op_of(x) == OpDecorate and len(x) > 3: deco.setdefault(x[1], {})[x[2]] = x[3]
    if any(DEC_BINDING not in deco.get(v, {}) for v in cand): return spv, None
    by_t = {}   # one sampled image type for all (the template's parameters take it): the most common; the others stay as they are
    for v, t in cand.items(): by_t.setdefault(t, []).append(v)
    tsel = max(by_t, key=lambda t: (len(by_t[t]), -t))
    vars_ = sorted(by_t[tsel], key=lambda v: deco[v][DEC_BINDING])[:max_cands]
    fb = 0 if hazard(m) else 1
    return _merge(m, template(fb), tsel, vars_, deco, fb)


def _merge(m, L, tsel, vars_, deco, fb):
    nl = L.names(); by_name = {}
    for i, n in nl.items(): by_name.setdefault(n.split('(')[0], i)
    f_qlod, f_sample, main_L = by_name['vt_qlod'], by_name['vt_sample'], by_name['main']
    skip = {by_name[n] for n in ('vt_tmpl_orig', 'vt_tmpl_pool', 'vt_tmpl_in', 'vt_tmpl_out') if n in by_name}
    bound = [m.bound]
    def new_id(): bound[0] += 1; return bound[0] - 1
    idmap = {}
    # the template's sampled image of a float 2D array, its image and its UniformConstant pointer are the candidates' own (the calls pass the shader's variables)
    L_ptr = next(x[1] for x in L.ins if op_of(x) == OpTypePointer and x[2] == SC_UNIFORM_CONSTANT and op_of(L.defs[x[3]]) == OpTypeSampledImage)
    L_si = L.defs[L_ptr][3]; L_img = L.defs[L_si][2]
    m_ptr = m.defs[next(x[1] for x in m.ins if op_of(x) == OpVariable and x[2] == vars_[0])][1]
    idmap.update({L_si: tsel, L_img: m.defs[tsel][2], L_ptr: m_ptr})
    have = {}   # the shader's types and constants by their structure
    for x in m.ins[:m.first_function()]:
        op = op_of(x)
        if (op in TYPES and op not in AGGREGATES) or op in CONSTS: have.setdefault(_key(x, {}), result_id(x))
    gl_m = next((x[1] for x in m.ins if op_of(x) == OpExtInstImport and str_of(x[2:]) == 'GLSL.std.450'), None)
    caps_m = {x[1] for x in m.ins if op_of(x) == OpCapability}
    new_caps, new_imports, new_globals, new_deco, new_names = [], [], [], [], []
    for x in L.ins:
        op = op_of(x)
        if op == OpCapability and x[1] not in caps_m: new_caps.append(list(x))
        elif op == OpExtInstImport:
            if str_of(x[2:]) == 'GLSL.std.450' and gl_m is not None: idmap[x[1]] = gl_m
            else: r = new_id(); idmap[x[1]] = r; new_imports.append([x[0], r] + list(x[2:]))
        elif op == OpExtension: raise ValueError('the template declares an extension')
    def mapped(x):
        y = list(x)
        for i in id_operands(x):
            if y[i] in idmap: y[i] = idmap[y[i]]
            elif op_of(x) not in (OpName, OpMemberName): raise ValueError(f'template id {y[i]} not mapped (opcode {op_of(x)})')
        return y
    def add_type(x):   # a type or constant of the template: the shader's own when it has it, else a new one after the shader's
        r = result_id(x)
        if r in idmap: return
        op = op_of(x)
        if op not in AGGREGATES:
            k = _key(x, idmap)
            if k in have: idmap[r] = have[k]; return
        n = new_id(); idmap[r] = n; y = mapped(x); y[1 if op in RESULT_ONLY else 2] = n; new_globals.append(y)
        if op not in AGGREGATES: have[_key(y, {})] = n
    res_vars = {}
    for x in L.ins[:L.first_function()]:
        op = op_of(x)
        if op in TYPES or op in CONSTS: add_type(x)
        elif op == OpVariable and x[2] not in skip:
            r = new_id(); idmap[x[2]] = r; new_globals.append(mapped(x)); res_vars[x[2]] = r
    # the bindings: a pool a candidate, then vt_ctl, vt_pt, vt_fb, after the shader's own
    used = [d[DEC_BINDING] for d in deco.values() if DEC_BINDING in d]; nb = max(used) + 1 if used else 0
    pool_vars, pools = [], []
    for k in range(len(vars_)):
        pv = new_id(); pool_vars.append(pv); new_globals.append(mk(OpVariable, m_ptr, pv, SC_UNIFORM_CONSTANT))
        new_deco += [mk(OpDecorate, pv, DEC_SET, 0), mk(OpDecorate, pv, DEC_BINDING, nb)]; new_names.append(mk(OpName, pv, *lit_str(f'vt_pool_{k}'))); pools.append(nb); nb += 1
    binds = {}
    for nm in ('vt_ctl', 'vt_pt', 'vt_fb'):
        r = by_name.get(nm)
        if r is None or r not in res_vars: continue
        binds[nm] = nb; new_names.append(mk(OpName, res_vars[r], *lit_str(nm)))
        new_deco += [mk(OpDecorate, res_vars[r], DEC_SET, 0), mk(OpDecorate, res_vars[r], DEC_BINDING, nb)]; nb += 1
    mine = {result_id(g) for g in new_globals}   # what the template added (its decorations come along; the shader's types it shares keep theirs)
    for x in L.ins:
        op = op_of(x)
        if op == OpDecorate and x[1] in idmap and idmap[x[1]] in mine and not (x[1] in res_vars and x[2] in (DEC_SET, DEC_BINDING)): new_deco.append(mapped(x))
        elif op == OpMemberDecorate and x[1] in idmap and idmap[x[1]] in mine: new_deco.append(mapped(x))
    # the functions (all but the template's main); vt_qlod and vt_sample take their parameters that are not opaque by value: glslang passes `in` parameters as pointers to
    # function variables, which the shader's call sites have none of
    funcs, cur = [], None
    for x in L.ins[L.first_function():]:
        if op_of(x) == OpFunction: cur = [x]
        elif cur is not None: cur.append(x)
        if op_of(x) == OpFunctionEnd: funcs.append(cur); cur = None
    out_funcs = []
    for f in funcs:
        if f[0][2] == main_L: continue
        for x in f:
            r = result_id(x)
            if r is not None and r not in idmap and op_of(x) not in TYPES: idmap[r] = new_id()
        byval = f[0][2] in (f_qlod, f_sample)
        conv = {x[2]: L.defs[x[1]][3] for x in f if byval and op_of(x) == OpFunctionParameter and L.defs[x[1]][2] == SC_FUNCTION}
        sub = {x[2]: x[3] for x in f if op_of(x) == OpLoad and x[3] in conv}
        # a component of a vector parameter is read through an access chain with a constant index and a load: the load becomes OpCompositeExtract
        chain = {x[2]: (x[3], L.defs[x[4]][3]) for x in f if op_of(x) == 65 and len(x) == 5 and x[3] in conv and op_of(L.defs.get(x[4], [0])) == OpConstant}
        for x in f:
            for i in id_operands(x):
                if x[i] in conv and not (op_of(x) == OpLoad and i == 3) and not (op_of(x) == OpFunctionParameter and i == 2) and not (op_of(x) == 65 and i == 3 and x[2] in chain):
                    raise ValueError(f'template parameter {x[i]} used other than by a load or a constant access chain')
                if x[i] in chain and not (op_of(x) == OpLoad and i == 3) and not (op_of(x) == 65 and i == 2):
                    raise ValueError(f'template access chain {x[i]} used other than by a load')
        for x in f:
            op = op_of(x)
            if op == OpLoad and x[3] in conv: continue
            if op == 65 and x[2] in chain: continue
            if op == OpLoad and x[3] in chain:
                p, c = chain[x[3]]; out_funcs.append(mapped(mk(81, x[1], x[2], p, c))); continue   # OpCompositeExtract of the parameter itself
            y = [x[0]] + [sub.get(w, w) if i in id_operands(x) else w for i, w in enumerate(x[1:], 1)]
            if op == OpFunctionParameter and x[2] in conv: y[1] = conv[x[2]]
            if op == OpFunction and byval:
                ft = L.defs[x[4]]; ps = [conv.get(p[2], p[1]) for p in f if op_of(p) == OpFunctionParameter]
                y = mapped(y); y[4] = _fn_type(idmap, have, new_globals, new_id, ft[2], ps); out_funcs.append(y); continue
            out_funcs.append(mapped(y))
    # the shader's calls: a sample or query of a load of candidate k becomes a call with its variable, its pool and k
    k_of = {v: k for k, v in enumerate(vars_)}
    load_var = {x[2]: x[3] for x in m.ins if op_of(x) == OpLoad and x[3] in k_of}
    ukey = (OpTypeInt, ('l', 32), ('l', 0))
    if ukey not in have: u = new_id(); new_globals.insert(0, mk(OpTypeInt, u, 32, 0)); have[ukey] = u
    kc = []
    for k in range(len(vars_)):
        key = (OpConstant, ('i', have[ukey]), ('l', k))
        if key not in have: c = new_id(); new_globals.append(mk(OpConstant, have[ukey], c, k)); have[key] = c
        kc.append(have[key])
    fq, fs = idmap[f_qlod], idmap[f_sample]
    ins2, nq, ns = [], 0, 0
    for x in m.ins:
        op = op_of(x)
        if op == OpImageSampleExplicitLod and x[3] in load_var and len(x) == 7 and x[5] == 2:
            k = k_of[load_var[x[3]]]; ins2.append(mk(OpFunctionCall, x[1], x[2], fs, vars_[k], pool_vars[k], kc[k], x[4], x[6])); ns += 1; continue
        if op == OpImageQueryLod and x[3] in load_var and len(x) == 5:
            k = k_of[load_var[x[3]]]; ins2.append(mk(OpFunctionCall, x[1], x[2], fq, vars_[k], kc[k], x[4])); nq += 1; continue
        ins2.append(x)
    # the module's sections, the template's after the shader's in each (its types may name the shader's, never the other way round)
    sec = {s: [] for s in ('cap', 'ext', 'imp', 'mm', 'ep', 'em', 'dbg', 'ann', 'glob', 'fn')}
    for x in ins2:
        op = op_of(x)
        s = 'fn' if sec['fn'] or op == OpFunction else 'cap' if op == OpCapability else 'ext' if op == OpExtension else 'imp' if op == OpExtInstImport else \
            'mm' if op == OpMemoryModel else 'ep' if op == OpEntryPoint else 'em' if op in (OpExecutionMode, 331) else \
            'dbg' if op in (OpName, OpMemberName, OpString, 2, 3, 4, 330) else 'ann' if op in (OpDecorate, OpMemberDecorate, 73, 74, 75, 332, 5632, 5633) else 'glob'
        sec[s].append(x)
    early = False
    if fb and not any(op_of(x) == OpExecutionMode and x[2] == EM_EARLY_FRAGMENT_TESTS for x in sec['em']):
        sec['em'].append(mk(OpExecutionMode, sec['ep'][0][2], EM_EARLY_FRAGMENT_TESTS)); early = True
    body = sec['cap'] + new_caps + sec['ext'] + sec['imp'] + new_imports + sec['mm'] + sec['ep'] + sec['em'] + sec['dbg'] + new_names + sec['ann'] + new_deco + \
           sec['glob'] + new_globals + sec['fn'] + out_funcs
    hdr = list(m.hdr); hdr[3] = bound[0]
    info = {'cands': [(deco[v][DEC_BINDING], k) for k, v in enumerate(vars_)], 'pools': pools, 'ctl': binds.get('vt_ctl'), 'pt': binds.get('vt_pt'),
            'fb': binds.get('vt_fb'), 'early': early, 'queries': nq, 'samples': ns}
    return emit(hdr, body), info


def _fn_type(idmap, have, new_globals, new_id, ret, params):
    """The function type returning ret and taking params (template ids), the shader's own when it has it"""
    r = idmap.get(ret, ret); ps = [idmap.get(p, p) for p in params]
    key = (OpTypeFunction,) + (('i', r),) + tuple(('i', p) for p in ps)
    if key not in have:
        n = new_id(); new_globals.append(mk(OpTypeFunction, n, r, *ps)); have[key] = n
    return have[key]


if __name__ == '__main__':
    if sys.argv[1:] == ['--regen']:
        import re
        sha, out = regen()
        path = __file__; src = open(path, encoding='utf-8').read()
        src = re.sub(r"^TEMPLATE_SHA = '[0-9a-f]*'$", f"TEMPLATE_SHA = '{sha}'", src, count=1, flags=re.M)
        src = re.sub(r"^TEMPLATE_SPV = \{.*\}$", "TEMPLATE_SPV = {1: '" + out[1] + "', 0: '" + out[0] + "'}", src, count=1, flags=re.M)
        open(path, 'w', encoding='utf-8').write(src)
        print(f'template {sha[:12]}: {len(base64.b64decode(out[1]))} + {len(base64.b64decode(out[0]))} bytes of SPIR-V')
        sys.exit(0)
    if len(sys.argv) != 3: print('spv_vt.py <in.spv> <out.spv> | --regen'); sys.exit(2)
    spv2, info = transform(open(sys.argv[1], 'rb').read())
    open(sys.argv[2], 'wb').write(spv2)
    print(info)
